const zone = 'Europe/Paris'
const hour = new Intl.DateTimeFormat('fr-FR', { timeZone: zone, hour: '2-digit', hourCycle: 'h23' })
const clock = new Intl.DateTimeFormat('fr-FR', { timeZone: zone, hour: '2-digit', minute: '2-digit' })
const dayLabel = new Intl.DateTimeFormat('fr-FR', { timeZone: zone, weekday: 'long', day: 'numeric', month: 'long' })
export function addDays(day, count) {
  const value = new Date(`${day}T12:00:00Z`)
  value.setUTCDate(value.getUTCDate() + count)
  return value.toISOString().slice(0, 10)
}
export function matchesPeriod(slot, period) {
  const morning = Number(hour.formatToParts(new Date(slot.start)).find(part => part.type === 'hour').value) < 12
  return period === 'all' || (period === 'morning' ? morning : !morning)
}

export function initSlotPicker({ date, slots, status, onSelect }) {
  const filters = [...document.querySelectorAll('[data-period]')]
  const next = document.querySelector('#booking-next')
  const retry = document.querySelector('#booking-retry')
  let period = 'all', days = [], selected = null, busy = false, locked = false, generation = 0, abort
  function controls() {
    next.disabled = busy || locked
    retry.disabled = busy || locked
    date.disabled = locked
    filters.forEach(button => { button.disabled = locked })
    slots.querySelectorAll('button').forEach(button => { button.disabled = locked })
  }
  function clearSelection() { selected = null; onSelect(null) }
  function render() {
    slots.replaceChildren()
    let count = 0
    for (const day of days) {
      const available = day.slots.filter(slot => matchesPeriod(slot, period))
      if (!available.length) continue
      count += available.length
      const section = document.createElement('section')
      const title = document.createElement('h4')
      title.textContent = dayLabel.format(new Date(`${day.date}T12:00:00Z`))
      const group = document.createElement('div')
      group.className = 'booking-day-times'
      for (const slot of available) {
        const button = document.createElement('button')
        button.type = 'button'
        button.textContent = clock.format(new Date(slot.start))
        button.setAttribute('aria-label', `${title.textContent} à ${button.textContent}`)
        button.setAttribute('aria-pressed', String(selected?.id === slot.id))
        button.addEventListener('click', () => {
          if (locked) return
          selected = slot
          slots.querySelectorAll('button').forEach(item => item.setAttribute('aria-pressed', String(item === button)))
          onSelect(slot)
        })
        group.append(button)
      }
      section.append(title, group)
      slots.append(section)
    }
    if (busy) status.textContent = count ? 'Créneaux disponibles ci-dessous. Recherche des jours suivants…' : 'Recherche des prochains créneaux…'
    else status.textContent = count ? 'Choisissez votre créneau ci-dessous.' : 'Aucun créneau pour ce filtre sur ces 7 jours. Changez de filtre ou consultez les jours suivants.'
    controls()
  }
  async function load() {
    abort?.abort()
    const current = ++generation
    abort = new AbortController()
    const requestController = abort
    const signal = requestController.signal
    clearSelection()
    days = []
    retry.hidden = true
    busy = true
    slots.setAttribute('aria-busy', 'true')
    render()
    const start = date.value
    if (!start || !date.validity.valid) {
      busy = false
      render()
      slots.setAttribute('aria-busy', 'false')
      status.textContent = 'Choisissez une date à partir d’aujourd’hui.'
      return
    }
    try {
      // Une semaine par recherche, en séquence : pas de rafale vers le calendrier Microsoft.
      for (let offset = 0; offset < 7; offset++) {
        const day = addDays(start, offset)
        const timeout = setTimeout(() => requestController.abort(), 15000)
        try {
          const response = await fetch(`/api/booking/availability?date=${day}`, { signal, cache: 'no-store' })
          if (!response.ok) throw Error('availability')
          const data = await response.json()
          if (!Array.isArray(data.slots) || data.slots.some(slot => !slot.id || !Number.isFinite(Date.parse(slot.start)))) throw Error('invalid slots')
          if (current !== generation) return
          days.push({ date: day, slots: data.slots.sort((a,b) => Date.parse(a.start) - Date.parse(b.start)) })
          render()
        } finally { clearTimeout(timeout) }
      }
      if (current !== generation) return
      busy = false
      render()
    } catch {
      if (current !== generation) return
      busy = false
      render()
      retry.hidden = false
      status.textContent = days.length ? 'Recherche incomplète. Les créneaux affichés sont disponibles ; réessayez pour vérifier les autres jours.' : 'Les disponibilités ne se chargent pas. Réessayez ou appelez le 07 67 01 21 02.'
    } finally {
      if (current === generation) { slots.setAttribute('aria-busy', 'false'); controls() }
    }
  }
  filters.forEach(button => button.addEventListener('click', () => {
    if (locked) return
    period = button.dataset.period
    filters.forEach(item => item.setAttribute('aria-pressed', String(item === button)))
    if (selected && !matchesPeriod(selected, period)) clearSelection()
    render()
  }))
  date.value = date.min
  date.addEventListener('change', () => { if (!locked) load() })
  next.addEventListener('click', () => { date.value = addDays(date.value || date.min, 7); load() })
  retry.addEventListener('click', load)
  load()
  return { refresh: load, setLocked(value) { locked = value; controls() } }
}

